    import time

    LANGUAGE_WRAPPER = 'Consider a {dimension}-dimensional rectangular box with strictly increasing positive integer side lengths x_1 < x_2 < ... < x_{dimension}. Its volume is exactly half the volume of the box obtained by adding the fixed integer offset {offset} to each side length. Additionally, the smallest {coprime_count} side lengths are pairwise coprime. Determine the largest possible value of x_{dimension}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We choose even offsets to ensure the coprimality condition gcd(a+1, 2a^2+a+1)=1 holds.
# Dimension is fixed at 4, and we require the smallest 2 side lengths to be coprime.
# We also ensure the instance is non-trivial by verifying the resulting maximum x_4 is large.
def compute_q_max(a):
    # Closed-form maximizing construction (see verifier notes):
    m = a + 1
    n = 2*a*a + a + 1
    # num2 = (m+a)*(n+a) = (2a+1)*(2a^2+2a+1)
    num2 = (2*a + 1) * (2*a*a + 2*a + 1)
    p = a * num2 + 1  # minimal p producing the closest-to-2 product and integrality
    # q = a * num2 * (p + a)
    q = a * num2 * (p + a)
    return q
for _ in range(50):
    offset = rng.choice([2, 4, 6])
    dimension = 4
    coprime_count = 2
    q_max = compute_q_max(offset)
    # Difficulty gate: ensure answer is large enough to avoid triviality
    if q_max >= 1000:
        return {'offset': offset, 'dimension': dimension, 'coprime_count': coprime_count}
# Fallback deterministic instance
return {'offset': 2, 'dimension': 4, 'coprime_count': 2}

    def verifier(assign):
# Verify domain constraints and compute the maximum x_d (here d=4) according to a proven maximizing construction.
# The core identity is: 2 * (x1 * x2 * x3 * x4) = (x1 + a)(x2 + a)(x3 + a)(x4 + a), with a = offset.
# Constraints: x1 < x2 < x3 < x4 are positive integers; gcd(x1, x2) = 1.
# Maximizer (proved in notes): for even a, take x1 = a+1 and x2 = 2a^2 + a + 1; then the minimal x3 making
# (1 + a/x1)(1 + a/x2)(1 + a/x3) < 2 is x3 = a * (x1 + a)(x2 + a) + 1, and this choice also yields integer x4,
# with x4 = a * (x1 + a)(x2 + a)(x3 + a). This produces the global maximum of x4 under the constraints.
try:
    a = int(assign.get('offset'))
    d = int(assign.get('dimension'))
    t = int(assign.get('coprime_count'))
except Exception:
    # Invalid types
    return (False, None)
# Basic validations
if d != 4:
    # Only d=4 is supported by this family
    return (False, None)  # invalid instance
if t != 2:
    # The construction and proof assume gcd condition on the smallest two
    return (False, None)
if a <= 0 or a % 2 != 0:
    # Require positive even offset to guarantee gcd(x1, x2)=1 in the maximizer
    return (False, None)
# Construct the extremal tuple
x1 = a + 1
x2 = 2*a*a + a + 1
# Check gcd(x1, x2) = 1
import math
if math.gcd(x1, x2) != 1:
    return (False, None)
# num2 = (x1 + a)(x2 + a) = (2a+1)(2a^2 + 2a + 1)
num2 = (2*a + 1) * (2*a*a + 2*a + 1)
# x3 chosen minimally so that the triple product is just below 2, and ensures integrality of x4
x3 = a * num2 + 1
# x4 computed from exact identity: 2*x1*x2*x3*x4 = (x1+a)(x2+a)(x3+a)(x4+a)
# Using the product-of-factors approach, this construction yields denominator 1, so:
x4 = a * num2 * (x3 + a)
# Validate strict increase
if not (x1 < x2 < x3 < x4):
    return (False, None)
# Validate the equation exactly
lhs = 2 * x1 * x2 * x3 * x4
rhs = (x1 + a) * (x2 + a) * (x3 + a) * (x4 + a)
if lhs != rhs:
    return (False, None)
# Difficulty gate
if x4 < 1000:
    return (False, None)
answer = x4
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

